def die(m):
    print("ABORTA: " + m)
    sys.exit(1)

def sha_b(b):
    return hashlib.sha256(b).hexdigest()

def sha(p):
    return sha_b(open(p, "rb").read())

if len(sys.argv) != 2 or sys.argv[1] not in ("--check", "--apply"):
    die("uso: --check | --apply")
APPLY = sys.argv[1] == "--apply"
if not (os.path.isfile("Makefile") and os.path.isdir("sniffer/src/userspace")):
    die("no estoy en la raiz del repo")

def aplicado():
    return (all(os.path.isfile(p) and sha(p) == e["despues"] for p, e in EDITS.items())
            and all(os.path.isfile(p) and sha(p) == sha_b(c.encode("utf-8")) for p, c in NUEVOS.items())
            and all(not os.path.exists(p) for p in BORRAR))

if aplicado():
    print("[YA APLICADO] paso 2 hecho. Nada que hacer.")
    sys.exit(0)
nuevos = {}
for p, e in EDITS.items():
    if not os.path.isfile(p):
        die(f"falta {p}")
    s = sha(p)
    if s != e["antes"]:
        die(f"{p} sha256 {s} no es el de partida (estado mixto o fichero cambiado)")
    t = open(p, encoding="utf-8").read()
    for a, b in e["rep"]:
        if t.count(a) != 1:
            die(f"{p}: ancla x{t.count(a)} (esperado 1): {a[:60]!r}")
        t = t.replace(a, b)
    if sha_b(t.encode("utf-8")) != e["despues"]:
        die(f"{p}: el resultado no tendria el sha256 esperado")
    nuevos[p] = (t, len(e["rep"]))
for p in NUEVOS:
    if os.path.exists(p):
        die(f"{p} ya existe y no es el esperado (estado mixto)")
    if not os.path.isdir(os.path.dirname(p)):
        die(f"no existe el directorio de {p}")
for p, s in BORRAR.items():
    if not os.path.isfile(p):
        die(f"falta {p} (a borrar)")
    if sha(p) != s:
        die(f"{p} sha256 {sha(p)} no es el de partida (a borrar)")
for p, (_, n) in nuevos.items():
    print(f"[OK] editar {p} ({n} bloques)")
for p in NUEVOS:
    print(f"[OK] crear {p}")
for p in BORRAR:
    print(f"[OK] borrar {p}")
if not APPLY:
    print("[CHECK] todo valida; nada escrito. Repite con --apply.")
    sys.exit(0)
for p, (t, _) in nuevos.items():
    tmp = p + ".d308tmp"
    with open(tmp, "w", encoding="utf-8", newline="") as f:
        f.write(t)
    shutil.copymode(p, tmp)
    os.replace(tmp, p)
for p, c in NUEVOS.items():
    with open(p, "w", encoding="utf-8", newline="") as f:
        f.write(c)
for p in BORRAR:
    os.remove(p)
if not aplicado():
    die("verificacion posterior fallida")
print("[APLICADO] paso 2.")
